package hk.jimmy.wearmemory;
import android.app.*; import android.content.*; import android.os.*; import android.graphics.Color; import android.view.*; import android.widget.*; import java.io.*; import java.text.*; import java.util.*;
import android.media.*;import com.google.android.gms.wearable.*;import java.util.concurrent.*;
public class RecordService extends Service {
private volatile boolean running;private Thread thread;private AudioRecord mic; private android.os.PowerManager.WakeLock lock;
public int onStartCommand(Intent i,int f,int id){if(running)return START_NOT_STICKY;if(checkSelfPermission("android.permission.RECORD_AUDIO")!=0){stopSelf();return START_NOT_STICKY;}NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("record","錄音狀態",NotificationManager.IMPORTANCE_LOW));startForeground(1,new Notification.Builder(this,"record").setSmallIcon(android.R.drawable.ic_btn_speak_now).setContentTitle("Memory 正在錄音").setContentText("開啟 App 可停止").setContentIntent(PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE)).build());running=true;lock=((PowerManager)getSystemService(POWER_SERVICE)).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"memory:record");lock.acquire();thread=new Thread(this::record);thread.start();return START_NOT_STICKY;}
void record(){int size=Math.max(32000,AudioRecord.getMinBufferSize(16000,16,2));try{mic=new AudioRecord(MediaRecorder.AudioSource.MIC,16000,16,2,size);mic.startRecording();byte[] buf=new byte[size];while(running){if(getFilesDir().getUsableSpace()<100L*1024*1024)throw new IOException("手錶空間不足，錄音已停止");long start=System.currentTimeMillis();File temp=new File(Ui.dir(this,"audio"),start+".pcm.part");try(FileOutputStream out=new FileOutputStream(temp)){long count=0;while(running&&count<16000L*2*300){int n=mic.read(buf,0,(int)Math.min(buf.length,16000L*2*300-count));if(n<0)throw new IOException("Microphone read "+n);if(n>0){out.write(buf,0,n);count+=n;}}out.getFD().sync();}if(temp.length()>0){File done=new File(temp.getPath().replace(".part",""));if(!temp.renameTo(done))throw new IOException("Commit failed");sync(this);}else temp.delete();}}catch(Exception e){Ui.notify(this,9,"錄音已中斷",e.toString());}finally{running=false;if(mic!=null){try{mic.stop();}catch(Exception ignored){}mic.release();}if(lock!=null&&lock.isHeld())lock.release();stopSelf();}}
static void sync(Context c){new Thread(()->{File[] files=Ui.dir(c,"audio").listFiles((d,n)->n.endsWith(".pcm"));if(files==null)return;for(File f:files)try(android.os.ParcelFileDescriptor fd=android.os.ParcelFileDescriptor.open(f,android.os.ParcelFileDescriptor.MODE_READ_ONLY)){PutDataMapRequest r=PutDataMapRequest.create("/recordings/"+f.getName());r.getDataMap().putAsset("audio",Asset.createFromFd(fd));r.getDataMap().putLong("timestamp",Long.parseLong(f.getName().replace(".pcm","")));com.google.android.gms.tasks.Tasks.await(Wearable.getDataClient(c).putDataItem(r.asPutDataRequest()));}catch(Exception ignored){}}).start();}
public void onDestroy(){running=false;super.onDestroy();}public IBinder onBind(Intent i){return null;}}
